"use client";

import { useRef } from "react";
import { gsap } from "gsap";
import { useGSAP } from "@gsap/react";

gsap.registerPlugin(useGSAP);

export function Hero() {
  const heroRef = useRef<HTMLElement>(null);
  const titleRef = useRef<HTMLHeadingElement>(null);
  const subtitleRef = useRef<HTMLParagraphElement>(null);

  useGSAP(
    () => {
      const elements = [titleRef.current, subtitleRef.current].filter(
        (element): element is HTMLElement => element !== null,
      );

      const media = gsap.matchMedia();

      media.add("(prefers-reduced-motion: reduce)", () => {
        gsap.set(elements, {
          clearProps: "opacity,transform,willChange",
        });
      });

      media.add("(prefers-reduced-motion: no-preference)", () => {
        gsap
          .timeline({
            defaults: {
              ease: "power3.out",
            },
            onComplete: () => {
              gsap.set(elements, {
                clearProps: "opacity,transform,willChange",
              });
            },
          })
          .fromTo(
            titleRef.current,
            {
              autoAlpha: 0,
              y: 24,
            },
            {
              autoAlpha: 1,
              y: 0,
              duration: 0.8,
            },
          )
          .fromTo(
            subtitleRef.current,
            {
              autoAlpha: 0,
              y: 16,
            },
            {
              autoAlpha: 1,
              y: 0,
              duration: 0.65,
            },
            "-=0.5",
          );
      });

      return () => media.revert();
    },
    { scope: heroRef },
  );

  return (
    <section
      ref={heroRef}
      aria-labelledby="hero-title"
      className="relative isolate flex min-h-[80svh] items-center overflow-hidden bg-[#11110f] px-6 py-24 text-[#f4f0e7] sm:px-10 lg:px-16"
    >
      <div
        aria-hidden="true"
        className="absolute inset-0 -z-10 bg-[radial-gradient(circle_at_75%_25%,rgba(213,180,113,0.14),transparent_38%)]"
      />

      <div className="mx-auto w-full max-w-6xl">
        <div className="max-w-4xl">
          <h1
            ref={titleRef}
            id="hero-title"
            className="text-balance text-5xl font-semibold leading-[0.95] tracking-[-0.045em] sm:text-7xl lg:text-8xl"
            style={{
              opacity: 0,
              transform: "translate3d(0, 24px, 0)",
              willChange: "transform, opacity",
            }}
          >
            Creamos experiencias que dejan huella.
          </h1>

          <p
            ref={subtitleRef}
            className="mt-8 max-w-2xl text-pretty text-lg leading-relaxed text-[#bdb8ae] sm:text-xl"
            style={{
              opacity: 0,
              transform: "translate3d(0, 16px, 0)",
              willChange: "transform, opacity",
            }}
          >
            Diseño y tecnología unidos para convertir ideas ambiciosas en
            productos digitales claros, memorables y efectivos.
          </p>
        </div>
      </div>
    </section>
  );
}
```

El estado inicial está en el propio JSX para evitar el flash previo a GSAP durante SSR. También incluye cleanup, animación limitada a `transform` y `opacity`, y soporte para `prefers-reduced-motion`.
